static inline uint16_t pdr16_xt_rom_read_word(uint16_t addr) {
    const uint16_t chunk_index = addr / PDR16_XT_ROM_CHUNK_WORDS;
    const uint16_t chunk_offset = addr % PDR16_XT_ROM_CHUNK_WORDS;
    switch (chunk_index) {
        case 0u:
            return pgm_read_word_far(pgm_get_far_address(pdr16_xt_forth_rom_chunk_0) + ((uint32_t)chunk_offset * 2u));
        case 1u:
            return pgm_read_word_far(pgm_get_far_address(pdr16_xt_forth_rom_chunk_1) + ((uint32_t)chunk_offset * 2u));
        case 2u:
            return pgm_read_word_far(pgm_get_far_address(pdr16_xt_forth_rom_chunk_2) + ((uint32_t)chunk_offset * 2u));
        case 3u:
            return pgm_read_word_far(pgm_get_far_address(pdr16_xt_forth_rom_chunk_3) + ((uint32_t)chunk_offset * 2u));
        default:
            return 0xFFFFu;
    }
}

